'use strict';
const CaseWorkbench=(()=>{
 const I=CaseImport,E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const sample='用例编号\t用例名称\t前置条件\t操作步骤\t预期结果\t测试输入\t优先级\nPDF-001\t核对PDF额定电压\t设备说明PDF已上传\t提问额定电压\t回答12V，并引用第1页\t额定电压是多少？\tP0\nPDF-002\t资料缺失时说明无法回答\tPDF没有保修年限\t询问保修年限\t说明资料未提供，不编造\t保修几年？\tP1\nPDF-003\t检查生成文件版面\t已提出PDF整理任务\t打开产物检查版面\t表格不截断、数字清晰\t整理参数表\tP1';
 function state(st){return st.case_workbench||=( {step:0,tab:'table',object_type:'agent',elements:[],reuse_manual:true,text:sample,namespace:'Office-PDF',header:0,layout:'row',sheets:[],mapping:{},cases:[],errors:[],entries:[],message:''});}
 const extraFields=[['interaction','interaction_stop','交互停止条件','例如：收到拒绝后停止，最多1轮'],['state','initial_state','初始状态','例如：功能开启、车门已关闭'],['state','state_observation','状态观测方式','例如：读取车辆实际状态接口'],['constraints','forbidden_effects','禁止结果','例如：拒绝后不得发送车控'],['constraints','cleanup','结束后的恢复','例如：清理本次待交互请求']];
 const button=(t,a,attrs='')=>`<button type="button" data-act="ci-${a}" ${attrs}>${t}</button>`;
 const options=(rows,v)=>rows.map(([k,l])=>`<option value="${E(k)}" ${String(k)===String(v)?'selected':''}>${E(l)}</option>`).join('');
 const table=(h,rows)=>`<div class="table-scroll"><table><thead><tr>${h.map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
 function programs(st){return st.implementations.filter(x=>x.kind==='executor').map(x=>[x.ref,x.name+' / '+x.version]);}
 function sampleEntries(st){const program=state(st).program||programs(st)[0][0];return [{title:'核对PDF额定电压',program_version:program,selector:'tests/test_pdf.py::test_voltage',case_refs:['Office-PDF:PDF-001'],parameters:[{key:'question',required:true}],file:'tests/test_pdf.py'}, {title:'资料缺失时说明无法回答',program_version:program,selector:'tests/test_pdf.py::test_missing',case_refs:['Office-PDF:PDF-002'],parameters:[{key:'question',required:true}],file:'tests/test_pdf.py'},{title:'检查生成文件版面',program_version:program,selector:'tests/test_layout.py::test_layout[portrait]',case_refs:[],parameters:[]},{title:'检查生成文件版面',program_version:program,selector:'tests/test_layout.py::test_layout[landscape]',case_refs:[],parameters:[]}];}
 function openDraft(st,d){const w=state(st),s=d.spec;w.object_type=s.object_type||'agent';w.elements=s.case_elements||[];w.reuse_manual=true;w.namespace=s.source_namespace||d.source;w.cases=[{object_type:s.object_type||'agent',case_elements:[...(s.case_elements||[])],base_spec:structuredClone(s),draft_id:d.id,title:d.name,objective:s.objective,requirements:{interaction_stop:s.interaction_stop||'',initial_state:s.initial_state||'',state_observation:s.state_observation||'',forbidden_effects:(s.forbidden_effects||[]).join('\n'),cleanup:(s.cleanup||[]).join('\n')},preconditions:(s.preconditions||[]).join('\n'),steps:(s.manual_steps||[]).map(x=>({step_id:x.step_id,action:x.action_text,expected:s.inline_expected?.steps?.find(y=>y.step_id===x.step_id)?.text||''})),input:s.inline_inputs?.text||'',source_namespace:s.source_namespace||d.source,source_case_id:s.source_case_id||'',source_rows:s.source_rows||[],source_snapshot:s.source_snapshot||{},priority:s.priority,tags:(s.tags||[]).join(','),execution_mode:s.execution_mode||'manual',binding:s.automation?.selector?s.automation:null,gaps:[]}];w.program=s.automation?.program_version||programs(st)[0]?.[0];const found=sampleEntries(st),keys=new Set(w.entries.map(e=>e.program_version+'|'+e.selector));w.entries.push(...found.filter(e=>!keys.has(e.program_version+'|'+e.selector)));w.step=3;w.message='正在关联当前用例：'+d.name;}
 function applyAssociations(w,rows,program){const links=I.importEntries(rows,program,w.namespace),changes=[];for(const link of links){const candidates=w.cases.filter(c=>link.case_refs.includes(c.source_namespace+':'+c.source_case_id));if(candidates.length>1)throw Error('待关联业务用例的来源编号重复，请先处理');if(!candidates.length)continue;const existing=w.entries.find(e=>e.program_version===program&&e.selector===link.selector);if(!existing)throw Error('当前程序发现清单中不存在入口：'+link.selector+'；先完成程序发现');changes.push({c:candidates[0],selector:link.selector});}for(const {c,selector} of changes)c.suggested_selector=selector;w.matches=null;w.message='关联表识别'+changes.length+'条，未找到本批业务用例'+(links.length-changes.length)+'条；请预览批量关联后确认。';}
 function legacyView(st){const w=state(st),header=w.matrix?.[w.header]||[],program=w.program||programs(st)[0]?.[0];const policy=CasePolicy.decide(w);let body='';
 if(w.step===0)body=`<p>先保存业务用例；没有自动化脚本也可以完成导入。已有Excel／飞书表格可直接用原列名。</p><div class="actions">${button('新建一条','new')}${button('表格导入','table')}${button('从自动化代码发现','code')}</div><label class="field">来源范围<input id="ci-namespace" value="${E(w.namespace)}"><small>如Office-PDF。与原用例编号一起用于去重和自动关联。</small></label>${w.tab==='code'?`<label class="field">自动化程序固定版本<select id="ci-program">${options(programs(st),program)}</select></label><p>选择项目中已登记的自动化程序，收集测试入口、用例编号、参数实例及输出能力；不会将函数名当成完整业务预期。</p>${button('载入代码发现示例','discover')}<details><summary>平台约定的代码标记示例</summary><pre>@pytest.mark.case_id("Office-PDF:PDF-001")\ndef test_voltage():\n    ...</pre><p>case_id是项目登记的自定义标记。平台在固定版本环境中收集；参数化实例分别展示，不在浏览器执行代码。</p></details>`:w.tab==='new'?`<div class="form-grid">${['用例名称','前置条件','操作步骤','预期结果','测试输入'].map((x,i)=>`<label class="field">${x}<textarea id="ci-new-${i}" rows="3">${E(w.new_values?.[i]||'')}</textarea></label>`).join('')}</div>${extraFields.filter(([e])=>w.elements.includes(e)).map(([,k,l,ph])=>`<label class="field">${l}<textarea id="ci-extra-${k}" placeholder="${ph}">${E(w.extra_values?.[k]||'')}</textarea></label>`).join('')}${button('保存为手工用例草稿','single')}`:`<label class="file-button">选择Excel／CSV文件<input id="ci-file" type="file" accept=".xlsx,.csv,.tsv"></label><label class="field">或从飞书表格复制后粘贴<textarea id="ci-source" rows="8">${E(w.text)}</textarea></label><div class="actions">${button('载入Office表格示例','example')}${button('解析表格并配置映射','parse')}</div>`}`;
 if(w.step===1)body=`<div class="form-grid"><label class="field">工作表<select id="ci-sheet">${options(w.sheets.map((s,i)=>[i,s.name]),w.sheet||0)}</select></label><label class="field">表头行<select id="ci-header">${options((w.matrix||[]).slice(0,12).map((r,i)=>[i,'第'+(i+1)+'行：'+r.join(' / ').slice(0,70)]),w.header)}</select></label><label class="field">每条用例的排版<select id="ci-layout">${options([['row','每行一个用例'],['steps','同一用例占多行步骤']],w.layout)}</select></label></div><p>下表选择每列存到哪里。未映射的原列保留在来源快照；不会自动拼成模型提示。</p>${table(['平台字段','原表格列','第一条实际值'],I.fields.map(([k,l])=>[l,`<select data-ci-map="${k}">${options([[-1,'不导入此项'],...header.map((h,i)=>[i,h||'空表头 '+(i+1)])],w.mapping[k]??-1)}</select>`,E(w.matrix[w.header+1]?.[w.mapping[k]]||'')]))}${button('预览解析后的用例','preview')}`;
 if(w.step===2)body=`<p>解析为 ${w.cases.length} 条用例，隔离 ${w.errors.length} 行；当前默认执行方式为手工。多行步骤保留顺序及对应预期。</p>${table(['来源编号／原行','用例名称','步骤 → 预期','待补齐'],w.cases.map(c=>[E(c.source_case_id||'无来源编号')+'<small>原行 '+c.source_rows.join('、')+'</small>',`<input data-ci-edit="${w.cases.indexOf(c)}|title" value="${E(c.title)}">`,c.steps.map((s,j)=>`<label>操作 ${j+1}<textarea data-ci-step="${w.cases.indexOf(c)}|${j}|action">${E(s.action)}</textarea></label><label>预期 ${j+1}<textarea data-ci-step="${w.cases.indexOf(c)}|${j}|expected">${E(s.expected)}</textarea></label>`).join('<hr>'),E(c.gaps?.join('、')||'内容已录入')+`<details><summary>调整本例验证要素</summary>${CasePolicy.elements.map(([k,l])=>`<label class="metric-choice"><input type="checkbox" data-ci-case-element="${w.cases.indexOf(c)}|${k}" ${(c.case_elements||[]).includes(k)?'checked':''}>${l}</label>`).join('')}${extraFields.filter(([e])=>(c.case_elements||[]).includes(e)).map(([,k,l])=>`<label>${l}<textarea data-ci-requirement="${w.cases.indexOf(c)}|${k}">${E(c.requirements?.[k]||'')}</textarea></label>`).join('')}</details>`]))}${w.errors.length?table(['原行','错误'],w.errors.map(x=>[x.line,E(x.reason)])):''}<div class="actions">${button('保存用例草稿，稍后关联自动化','save')}${button('继续关联自动化','automation')}</div>`;
 if(w.step===3)body=`<p>已有脚本选一次固定程序版本。按明确编号或入口批量关联；同名、多候选和无匹配保留待处理。未关联的用例仍可手工执行。</p><label class="field">自动化程序固定版本<select id="ci-program">${options(programs(st),program)}</select></label><div class="actions">${button('载入已发现的自动化清单示例','inventory')}${button('预览批量关联','match')}${button('确认全部唯一匹配','bind-all')}</div><details><summary>导入自动化关联表（Excel／CSV／飞书复制）</summary><p>列：来源范围、来源用例编号、用例名称、自动化入口。程序版本以上方选择为准。</p><input type="file" id="ci-inventory-file" accept=".xlsx,.csv,.tsv"><textarea id="ci-inventory" rows="4" placeholder="来源范围&#9;来源用例编号&#9;用例名称&#9;自动化入口"></textarea>${button('解析关联表','inventory-paste')}</details>${table(['业务用例','匹配依据／状态','逐条选择自动化入口','参数映射'],w.cases.map((c,i)=>{const m=w.matches?.[i],e=w.entries.find(x=>x.selector===c.binding?.selector&&x.program_version===program);return [E(c.title)+'<small>'+E(c.source_case_id)+'</small>',E(c.binding?'已关联；待检查和试跑':m?.reason||'未匹配'),`<select data-ci-bind="${i}">${options([['','保持手工／未关联'],...w.entries.filter(x=>x.program_version===program).map(x=>[x.selector,x.selector])],c.binding?.selector||'')}</select>`,(e?.parameters||[]).map(p=>`<label>${E(p.key)} ← <select data-ci-param="${i}|${E(p.key)}">${options([['','请选择来源'],...I.inputSources(c).map(s=>[s,s==='inputs.text'?'本例测试输入':s.slice(7)])],c.binding.parameter_mapping.find(m=>m.target===p.key)?.source||'')}</select></label>`).join('')||'无额外参数；沿用执行器输出映射'] ;}))}<div class="actions">${button('检查关联与参数','check')}${button('保存用例草稿及关联','save')}</div><p>返回与证据映射优先沿用所选执行器固定版本。检查只确认绑定和参数齐全；试跑、评分依据检查和发布确认仍在所选用例的执行配置中完成。</p>`;
 if(w.step===0&&!policy.needs_case)body=`<div class="intro-note"><strong>本次不需要用例</strong><p>${E(policy.reason)}</p>${button('去准备数据集与字段映射','data')}${button('继续管理已有手工用例','keep-manual')}</div>`;return `<div class="view-title"><h3>用例 · 新建／导入</h3>${button('返回资产中心','back')}</div>${w.step===0?`<div class="form-grid"><label class="field">评测对象类型<select id="ci-object-type">${options(CasePolicy.objectTypes,w.object_type)}</select></label><div>本次额外需要检查什么？<div>${CasePolicy.elements.map(([k,l])=>`<label class="metric-choice"><input type="checkbox" data-ci-element="${k}" ${w.elements.includes(k)?'checked':''}>${l}</label>`).join('')}</div></div></div><p>${E(policy.reason)} 对象类型只推荐默认项；文件输入本身不要求增加用例。</p>`:''}<div class="step-tabs">${['①选择来源','②解析与字段映射','③确认用例内容','④关联自动化（按需）'].map((t,i)=>button(t,'step',`data-step="${i}"`)).join('')}</div><p role="status">${E(w.message)}</p>${body}`;
 }
 function view(st){return typeof CaseUX!=='undefined'?CaseUX.view(st,state(st)):legacyView(st);}
 function action(st,a,b){if(a.startsWith('ux-'))return CaseUX.action(st,a.slice(3),b);const w=state(st),get=id=>document.getElementById(id)?.value;if(get('ci-namespace')!==undefined)w.namespace=get('ci-namespace');if(get('ci-program'))w.program=get('ci-program');if(get('ci-source')!==undefined)w.text=get('ci-source');if(a==='back')return 'back';if(a==='data')return 'data';if(a==='keep-manual')w.reuse_manual=true;if(a==='step'){const n=Number(b.dataset.step);if(n>0&&!w.matrix&&n<3)throw Error('先导入或新建用例');if(n>1&&!w.cases.length)throw Error('先预览用例内容');w.step=n;}
 if(['new','table','code'].includes(a)){w.tab=a;w.step=0;}
 if(a==='example'){w.text=sample;w.message='已载入三条Office用例表格，可直接改列名后解析。';}
 if(a==='parse'){const rows=I.parse(w.text,w.text.includes('\t')?'\t':',');if(!rows.length)throw Error('请上传或粘贴含表头的用例表');w.sheets=[{name:'粘贴表格',rows}];w.sheet=0;w.matrix=rows;w.header=0;w.mapping=I.guess(rows[0]);w.step=1;}
 if(a==='preview'){const r=I.normalize(w.matrix,{header:w.header,mapping:w.mapping,layout:w.layout,namespace:w.namespace});w.cases=r.cases.map(c=>({...c,object_type:w.object_type,case_elements:[...w.elements]}));w.errors=r.errors;w.step=2;}
 if(a==='single'){const vals=[0,1,2,3,4].map(i=>get('ci-new-'+i)||'');w.matrix=[['用例名称','前置条件','操作步骤','预期结果','测试输入'],vals];const r=I.normalize(w.matrix,{namespace:w.namespace});if(r.errors.length)throw Error(r.errors[0].reason);w.cases=r.cases.map(c=>({...c,object_type:w.object_type,case_elements:[...w.elements],requirements:Object.fromEntries(extraFields.filter(([e])=>w.elements.includes(e)).map(([,k])=>[k,get('ci-extra-'+k)||'']))}));w.errors=[];w.step=2;}
 if(a==='automation')w.step=3;
 if(a==='inventory'){const fresh=sampleEntries(st);const keys=new Set(fresh.map(e=>e.program_version+'|'+e.selector));w.entries=[...w.entries.filter(e=>!keys.has(e.program_version+'|'+e.selector)),...fresh];w.program=w.program||programs(st)[0][0];w.matches=null;w.message='自动化清单包含2条明确编号和2条同名参数实例。';}
 if(a==='discover'){w.entries=sampleEntries(st);w.program=w.program||programs(st)[0][0];w.cases=w.entries.map((e,i)=>({object_type:w.object_type,case_elements:[...w.elements],requirements:{},title:e.title+(w.entries.filter(x=>x.title===e.title).length>1?' · '+(e.selector.includes('[portrait]')?'纵向版式':'横向版式'):''),source_snapshot:{kind:'automation_discovery',program_version:e.program_version,selector:e.selector},source_namespace:w.namespace,source_case_id:(e.case_refs[0]||'').split(':').at(-1)||'',objective:'',preconditions:'',steps:[],source_rows:[],gaps:['补业务目标及预期','核对断言与必要记录'],input:'',execution_mode:'platform',binding:{program_version:e.program_version,selector:e.selector,parameter_mapping:[],result_mapping:[],binding_status:'BOUND',trial_status:'NOT_RUN'}}));w.step=3;w.message='从固定程序发现4个测试入口；未从函数名推断业务预期。';}
 if(a==='inventory-paste'){applyAssociations(w,I.parse(get('ci-inventory')||''),w.program||programs(st)[0][0]);}
 if(a==='match'){w.matches=w.cases.map(c=>I.match(c,w.entries,w.program||programs(st)[0][0]));w.message='唯一匹配可以批量确认；其他条目请逐条选择。';}
 if(a==='bind-all'){if(!w.matches)throw Error('先预览批量关联');w.cases=w.cases.map((c,i)=>!c.binding&&!c.keep_manual&&w.matches[i].status==='unique'?I.bind(c,w.matches[i].entry):c);w.message='已绑定唯一匹配；已有绑定、同名和冲突条目保持原值。';}
 if(a==='check'){if(!w.cases.some(c=>c.binding))throw Error('当前没有自动化关联；可直接保存为手工用例');const issues=w.cases.flatMap(c=>I.validateBindings(c,w.entries.find(e=>e.selector===c.binding?.selector&&e.program_version===(w.program||programs(st)[0][0]))).map(msg=>c.title+'：'+msg));w.message=issues.length?issues.join('；'):'关联与参数检查通过；仍需实际试跑和评分依据验证。';}
 if(a==='save'){if(!w.cases.length)throw Error('请先解析或新建用例');let added=0,existing=0;w.cases.forEach(c=>{let d=I.toDraft(c);if(c.draft_id){const idx=st.catalog_drafts.findIndex(x=>x.id===c.draft_id);if(idx>=0){const old=st.catalog_drafts[idx];const updated={...old,name:d.name,spec:{...old.spec,...d.spec}};if(AssetCatalog.fingerprint(old)!==AssetCatalog.fingerprint(updated)){delete updated.validation;delete updated.technical_confirmation;delete updated.business_confirmation;}st.catalog_drafts[idx]=updated;return;}}const prior=c.source_case_id?[...st.catalog_drafts,...st.assets].find(x=>x.catalog_key==='case'&&x.spec.source_namespace===c.source_namespace&&x.spec.source_case_id===c.source_case_id):[...st.catalog_drafts,...st.assets].find(x=>x.catalog_key==='case'&&x.spec.source_namespace===c.source_namespace&&JSON.stringify(x.spec.source_snapshot)===JSON.stringify(c.source_snapshot)&&x.name===c.title);if(prior){existing++;return;}c.draft_id=d.id;st.catalog_drafts.push(d);added++;});w.message='已新增 '+added+' 条用例草稿；'+existing+' 条已存在的来源记录保持不变，请在资产中心编辑草稿或为已发布版本创建新修订。返回资产中心可继续编辑、检查和发布。';}

 return '';
 }
 async function change(st,el){if(typeof CaseUX!=='undefined'&&CaseUX.change(st,el))return true;const w=state(st);w.new_values||={};w.extra_values||={};for(let i=0;i<5;i++){const x=document.getElementById('ci-new-'+i);if(x)w.new_values[i]=x.value;}for(const [,k]of extraFields){const x=document.getElementById('ci-extra-'+k);if(x)w.extra_values[k]=x.value;}if(document.getElementById('ci-source'))w.text=document.getElementById('ci-source').value;if(document.getElementById('ci-namespace'))w.namespace=document.getElementById('ci-namespace').value;if(el.id==='ci-object-type'){w.object_type=el.value;w.reuse_manual=false;return true;}if(el.dataset.ciElement){const k=el.dataset.ciElement;w.elements=el.checked?[...new Set([...w.elements,k])]:w.elements.filter(x=>x!==k);return true;}if(el.dataset.ciCaseElement){const [i,k]=el.dataset.ciCaseElement.split('|'),c=w.cases[i];c.case_elements=el.checked?[...new Set([...(c.case_elements||[]),k])]:(c.case_elements||[]).filter(x=>x!==k);return true;}if(el.dataset.ciRequirement){const [i,k]=el.dataset.ciRequirement.split('|');w.cases[i].requirements||={};w.cases[i].requirements[k]=el.value;return true;}if(el.dataset.ciEdit){const [i,k]=el.dataset.ciEdit.split('|');w.cases[i][k]=el.value;return true;}if(el.dataset.ciStep){const [i,j,k]=el.dataset.ciStep.split('|');w.cases[i].steps[j][k]=el.value;w.cases[i].gaps=[];return true;}if(el.dataset.ciMap){w.mapping[el.dataset.ciMap]=Number(el.value);return true;}if(el.dataset.ciBind!==undefined){const i=Number(el.dataset.ciBind);if(el.value==='__keep__')return true;if(el.value==='__recommend__'){w.cases[i].keep_manual=false;return true;}w.cases[i].keep_manual=!el.value;const entry=w.entries.find(e=>e.selector===el.value&&e.program_version===(w.program||programs(st)[0][0]));w.cases[i]=entry?I.bind(w.cases[i],entry):{...w.cases[i],execution_mode:'manual',binding:null};return true;}if(el.dataset.ciParam){const [i,target]=el.dataset.ciParam.split('|'),b=w.cases[Number(i)].binding;b.trial_status='NOT_RUN';b.parameter_mapping=b.parameter_mapping.filter(x=>x.target!==target);if(el.value)b.parameter_mapping.push({source:el.value,target,transform:'identity'});return true;}
 if(el.id==='ci-file'||el.id==='ci-inventory-file'){const file=el.files[0];if(!file)return true;const sheets=file.name.toLowerCase().endsWith('.xlsx')?await CaseWorkbook.read(await file.arrayBuffer()):[{name:file.name,rows:I.parse(await file.text(),file.name.endsWith('.csv')?',':'\t')}];if(el.id==='ci-inventory-file'){if(!w.entries.some(e=>e.program_version===(w.program||programs(st)[0][0])))w.entries.push(...sampleEntries(st));if(sheets.length!==1)throw Error('关联表请导出单个工作表后导入');applyAssociations(w,sheets[0].rows,w.program||programs(st)[0][0]);w.matches=w.cases.map(c=>I.match(c,w.entries,w.program||programs(st)[0][0]));w.autoStep=1;}else{w.sourceName=file.name;if(w.namespace==='用例表格')w.namespace=file.name;w.sheets=sheets;w.sheet=0;w.matrix=sheets[0].rows;w.header=0;w.mapping=I.guess(w.matrix[0]);w.step=1;}return true;}
 if(el.id==='ci-sheet'){w.sheet=Number(el.value);w.matrix=w.sheets[w.sheet].rows;w.header=0;w.mapping=I.guess(w.matrix[0]);return true;}if(el.id==='ci-header'){w.header=Number(el.value);w.mapping=I.guess(w.matrix[w.header]);return true;}if(el.id==='ci-layout'){w.layout=el.value;return true;}if(el.id==='ci-program'){w.program=el.value;w.matches=null;w.message='已切换程序版本；已有绑定仍保留原版本，需要检查或显式替换。';return true;}return false;
 }
 return {view,action,change,state,openDraft,applyAssociations};
})();
